import Grid from "@mui/material/Grid";


const AboutUs = () => {
  return (
    <>
      <section className="about-us-section">
        <Grid
          container
          direction="row"
          spacing={2}
          padding={5}
          justifyContent={"center"}
        >
          <Grid size={12} justifyContent={"center"}>
            
            <h6 className="p-5">¿Quienes somos?</h6>
          </Grid>
          <Grid size={{ md: 10, sm: 12 }}>
            <h3>
              Somos una empresa Familiar que presta servicios de contabilidad,
              recursos humanos, y asesoramiento fiscal.
            </h3>
            <p className="mt-5">
              Somos el mejor aliado para toda aquella persona física o jurídica
              que se encuentra inscrita en el misterio de Hacienda, prestamos
              servicios tanto a las Micro, pequeñas y medianas empresas,
              comerciales y de servicio que funcionan en diferentes sectores del
              mercado.
            </p>
          </Grid>

          <Grid size={{ md: 3, sm: 6 }}>
            <div className="about-us-card border-shadow-secondary">
              <h3>Transparencia</h3>
              <p>
                Logramos un buen desempeño laboral a través de nuestro
                compromiso de trabajar con integridad y transparencia para
                garantizar la justicia, mejorar la confianza, la credibilidad,
                la responsabilidad y tomar decisiones transparentes con la
                información financiera de la empresa.
              </p>
            </div>
          </Grid>

          <Grid size={{ md: 3, sm: 6 }}>
            <div className="about-us-card border-shadow-primary">
              <h3>Competitividad</h3>
              <p>
                Seguimos mejorando el desempeño de nuestro estudio y estamos
                interesados en la excelencia y anticiparnos al futuro para
                lograr el primer lugar en todas las áreas de nuestro trabajo
              </p>
            </div>
          </Grid>

          <Grid size={{ md: 3, sm: 6 }}>
            <div className="about-us-card border-shadow-secondary">
              <h3>Innovación</h3>
              <p>
                Buscamos transformar la innovación en trabajo de las empresas
                mediante el establecimiento de un entorno que estimule el
                pensamiento creativo y la construcción de personas con altas
                habilidades de innovación.
              </p>
            </div>
          </Grid>

          <Grid size={{ md: 3, sm: 6 }}>
            <div className="about-us-card border-shadow-primary">
              <h3>Confianza</h3>
              <p>
                Creemos en nuestra capacidad como personas, como empresa y como
                país
              </p>
            </div>
          </Grid>
        </Grid>
      </section>
    </>
  );
};

export default AboutUs;
