import Grid from '@mui/material/Grid';
import ImgActividades from '../../assets/img/actividades.png';
import ImgDeudas from '../../assets/img/deudas.png';
import ImgContabilidad from '../../assets/img/Contabilidad.png';
import ImgFinanciero from '../../assets/img/financiero.png';
import ImgHacienda from '../../assets/img/hacienda.png';
import ImgCpi from '../../assets/img/cpi.png';
import ImgFlujo from '../../assets/img/flujo.png';
import ImgPlanillas from '../../assets/img/planillas.png';

const Services = () => {
  return (
    <Grid container mt={3} padding={5} spacing={2}>
        <Grid size={12}>
            <p className='subtitle-services'>¿Qué ofrecemos?</p>
            <h2 className='title-services'>Nuestros Servicios</h2>
        </Grid>
        <Grid size={{ xs: 12, sm: 6,md: 3 }} >
            
            <div className='card-service'>
                <img src={ImgActividades} alt='Service 1' />
                <h3>Inscripción y desinscripción de Actividades</h3>
            </div>

        </Grid>
        <Grid size={{ xs: 12,sm: 6, md: 3 }} >
            
            <div className='card-service'>
                <img src={ImgDeudas} alt='Service 1' />
                <h3>Prescripción de deudas</h3>
            </div>

        </Grid>
        <Grid size={{ xs: 12, sm: 6,md: 3 }} >
            
            <div className='card-service'>
                <img src={ImgContabilidad} alt='Service 1' />
                <h3>Contabilidad Outsourcing</h3>
            </div>

        </Grid>
        <Grid size={{ xs: 12, sm: 6,md: 3 }} >
            
            <div className='card-service'>
                <img src={ImgFinanciero} alt='Service 1' />
                <h3>Estados Financieros para Entidades Bancarias</h3>
            </div>

        </Grid>

         <Grid size={{ xs: 12, sm: 6,md: 3 }} >
            
            <div className='card-service'>
                <img src={ImgCpi} alt='Service 1' />
                <h3>Certificación de Ingresos bajo CPI</h3>
            </div>

        </Grid>
        <Grid size={{ xs: 12, sm: 6,md: 3 }} >
            
            <div className='card-service'>
                <img src={ImgFlujo} alt='Service 1' />
                <h3>Preparación de Flujos de Caja Proyectados</h3>
            </div>

        </Grid>
        <Grid size={{ xs: 12, sm: 6, md: 3 }} >
            
            <div className='card-service'>
                <img src={ImgPlanillas} alt='Service 1' />
                <h3>Preparación y presentación de planillas CCSS/ INS</h3>
            </div>

        </Grid>
        <Grid size={{ xs: 12, sm: 6, md: 3 }} >
            
            <div className='card-service'>
                <img src={ImgHacienda} alt='Service 1' />
                <h3>Preparación y presentación de declaraciones ante el Ministerio de Hacienda</h3>
            </div>

        </Grid>
    </Grid>
  );
}

export default Services;