import Grid from "@mui/material/Grid";
import ApiIcon from '@mui/icons-material/Api';
import ImgExperiencia from "../../assets/img/experiencia.png";
import ImgAsesoramiento from "../../assets/img/asesoramiento.png";
import ImgDecisiones from "../../assets/img/decisiones.png";

const About = () => {
  return (
    <section className="about-section">
      <Grid
        container
        direction="row"
        sx={{ justifyContent: "flex-end", alignItems: "center" }}
        padding={5}
        spacing={2}
      >
        <Grid size={12}>
          <div className="about-img">
            <h1 className="p-5">¿Por qué elegirnos?</h1>
          </div>
        </Grid>
        <Grid size={{ xs: 12, md: 3 }}>
          <div className="about-card">
            <h3> <ApiIcon color='primary'></ApiIcon> Experiencia y conocimiento</h3>
            <p>
              Contamos con una amplia experiencia en el campo de la contabilidad
              y podemos ayudarle a mantenerse al día con sus obligaciones
              fiscales y financieras.
            </p>
            <img src={ImgExperiencia} alt='Experiencia' />
          </div>
        </Grid>

        <Grid size={{ xs: 12, md: 3 }}>
          <div className="about-card">
            <h3><ApiIcon color='primary'></ApiIcon> Asesoramiento personalizado</h3>
            <p>
              Nuestro enfoque es personalizado para cada cliente, lo que
              significa que pueden adaptar sus servicios para satisfacer las
              necesidades específicas de cada empresa.
            </p>
            <img src={ImgAsesoramiento} alt='Asesoramiento' />
          </div>
        </Grid>s
        
        <Grid size={{ xs: 12, md: 3 }}>
          <div className="about-card">
            <h3><ApiIcon color='primary'></ApiIcon> Decisiones empresariales</h3>
            <p>
              Al tener información financiera precisa y confiable, las empresas
              pueden tomar decisiones empresariales más informadas y
              estratégicas para el futuro de su negocio.
            </p>
            <img src={ImgDecisiones} alt='Decisiones' />
          </div>
        </Grid>
      </Grid>
    </section>
  );
};
export default About;
