import Grid from "@mui/material/Grid";
import Logo from "../../assets/img/logo.png";
import FacebookIcon from '@mui/icons-material/Facebook';

const Footer = () => {
  return (
    <>
      <footer className="footer">
        <div className="footer-content">
          <Grid container direction="row" spacing={2}>
            <Grid size={{ xs: 6, sm: 6, md: 8 }}>
              <img src={Logo} alt="logo" />
              <p className="ml-5">
                Servicios contables y asesoría fiscal en Costa Rica.
              </p>
              

              

            </Grid>
            <Grid size={{ xs: 6, sm: 6, md: 4 }}>
              <div className="card">

                <h3>Contacto</h3>
                <p>Teléfono: +506 8446 6551</p>
                <p>Email: info@keymacr.es</p>                
                
              </div>
            
              <p className="ml-5">Redes sociales</p>
              <ul className="socials ml-5">
                <li className="social-icon">
                  {" "}
                  <a className="text-primary ml-5" href="https://www.facebook.com/keymacr.es"> <FacebookIcon></FacebookIcon>Facebook</a>
                </li>
                
              </ul>
            </Grid>
            <Grid size={{ xs: 6, sm: 6, md: 4 }}>
              
            </Grid>
          </Grid>
        </div>
      </footer>
    </>
  );
};

export default Footer;
